  async Task Initialize(){try{library=await Task.Run(()=>ThemeRepository.Scan());devices=await Task.Run(()=>JonsboTransport.Discover());if(string.IsNullOrEmpty(settings.Port)||!devices.Exists(x=>x.port==settings.Port)){var preferred=devices.FirstOrDefault();settings.Port=preferred==null?"":preferred.port;}if(File.Exists(settings.ThemePath))current=ThemeDocument.Load(settings.ThemePath);else{var theme=library.FirstOrDefault(x=>x.name=="NIER")??library.FirstOrDefault(x=>x.width==1920&&x.height==462)??library.FirstOrDefault();if(theme!=null){current=ThemeDocument.Load(theme.path);settings.ThemePath=theme.path;}}
    LoadDeviceSettings();var resumePorts=deviceSettings.Where(x=>x.Value.Resume&&x.Value.WasPlaying&&devices.Any(d=>d.port==x.Key)&&File.Exists(x.Value.ThemePath)).Select(x=>x.Key).ToList();var environment=await CoreWebView2Environment.CreateAsync(null,AppPaths.Data("WebView2"));await web.EnsureCoreWebView2Async(environment);web.CoreWebView2.Settings.AreDefaultContextMenusEnabled=false;web.CoreWebView2.Settings.IsStatusBarEnabled=false;web.CoreWebView2.Settings.AreDevToolsEnabled=false;web.CoreWebView2.SetVirtualHostNameToFolderMapping("studio.local",AppPaths.Root,CoreWebView2HostResourceAccessKind.DenyCors);if(Directory.Exists(AppPaths.Installed))web.CoreWebView2.SetVirtualHostNameToFolderMapping("installed.local",AppPaths.Installed,CoreWebView2HostResourceAccessKind.DenyCors);
    web.CoreWebView2.NavigationStarting+=(s,e)=>{if(!e.Uri.StartsWith("https://studio.local/Assets/Web/index.html",StringComparison.OrdinalIgnoreCase))e.Cancel=true;};web.CoreWebView2.NewWindowRequested+=(s,e)=>e.Handled=true;web.CoreWebView2.WebMessageReceived+=Message;web.CoreWebView2.NavigationCompleted+=(s,e)=>{ready=e.IsSuccess;if(ready){SendAll();previewTimer=new System.Threading.Timer(PreviewTick,null,0,5);stateTimer.Start();}};web.CoreWebView2.Navigate("https://studio.local/Assets/Web/index.html");
