   }catch(Exception ex){status=ex.Message;MessageBox.Show(this,status,"JONSBO Studio",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
  void Post(object value){if(!ready||IsDisposed)return;var type=value.GetType().GetProperty("type");if(!windowVisible&&type!=null&&(string)type.GetValue(value,null)=="state")return;web.CoreWebView2.PostWebMessageAsJson(JsonConvert.SerializeObject(value));}
  string DeviceSettingsPath{get{return Path.Combine(AppPaths.Data("Settings"),"devices.json");}}
  void LoadDeviceSettings(){if(persist&&File.Exists(DeviceSettingsPath))try{var saved=JsonConvert.DeserializeObject<Dictionary<string,StudioSettings>>(File.ReadAllText(DeviceSettingsPath));if(saved!=null)foreach(var item in saved)if(!string.IsNullOrEmpty(item.Key)&&item.Value!=null){item.Value.Port=item.Key;deviceSettings[item.Key]=item.Value;}}catch{}if(!string.IsNullOrEmpty(settings.Port)&&!deviceSettings.ContainsKey(settings.Port))deviceSettings[settings.Port]=settings;foreach(var device in devices)if(!deviceSettings.ContainsKey(device.port)){var config=new StudioSettings{Port=device.port,Width=device.port==MsDisplayTransport.PortId?960:1920,Height=device.port==MsDisplayTransport.PortId?376:462,Fps=60,Quality=75,CacheMB=128,Rotation=-1,Resume=true};string name=device.port==MsDisplayTransport.PortId?"339H01.json":"NIER.json";var match=library.FirstOrDefault(x=>x.name==Path.GetFileNameWithoutExtension(name)&&x.width==config.Width&&x.height==config.Height);config.ThemePath=match==null?"":match.path;deviceSettings[device.port]=config;}StudioSettings active;if(deviceSettings.TryGetValue(settings.Port,out active)){settings=active;if(File.Exists(settings.ThemePath))current=ThemeDocument.Load(settings.ThemePath);}}
  void SelectDevice(string port){if(string.IsNullOrEmpty(port)||!devices.Any(x=>x.port==port))throw new InvalidOperationException("The selected display is not connected.");if(settings.Port==port)return;SaveSettings();StudioSettings next;if(!deviceSettings.TryGetValue(port,out next))throw new InvalidOperationException("The display has no settings yet.");settings=next;current=File.Exists(settings.ThemePath)?ThemeDocument.Load(settings.ThemePath):null;renderedFps=usbFps=previewFps=mbps=0;var active=engine;lastProduced=active==null?0:active.Produced;lastSent=active==null?0:active.Sent;lastBytes=active==null?0:active.Bytes;lastTick=clock.Elapsed.TotalSeconds;lastPreviewEngine=null;lastPreviewJpeg=null;Post(new{type="document",document=current==null?null:current.ForEditor()});status="Selected "+(devices.First(x=>x.port==port)).name+".";SendState();}
  void SendAll(){online=OnlineCatalog.BuiltIns();Post(new{type="library",items=library});Post(new{type="online",items=online});if(current!=null)Post(new{type="document",document=current.ForEditor()});SendState();}
  void Message(object sender,CoreWebView2WebMessageReceivedEventArgs e){if(!e.Source.StartsWith("https://studio.local/Assets/Web/",StringComparison.OrdinalIgnoreCase))return;try{var message=JObject.Parse(e.WebMessageAsJson);string action=(string)message["action"];if(action=="previewStats"){previewFps=Math.Max(0,Math.Min(120,(double?)message["fps"]??0));return;}if(action=="page"){previewPage=(string)message["page"]=="display";return;}HandleMessage(message);}catch(Exception ex){Post(new{type="error",message=ex.Message});}}
  async void HandleMessage(JObject message){string action=(string)message["action"]??"";try{if(busy&&action!="stop"&&action!="saveSettings")return;switch(action){
   case "init":SendAll();break;
   case "selectTheme":{var entry=library.Find(x=>x.id==(string)message["id"]);if(entry!=null){current=ThemeDocument.Load(entry.path);settings.ThemePath=entry.path;Post(new{type="document",document=current.ForEditor()});SaveSettings();}break;}
   case "applyTheme":{var entry=library.Find(x=>x.id==(string)message["id"]);if(entry!=null){current=ThemeDocument.Load(entry.path);settings.ThemePath=entry.path;Post(new{type="document",document=current.ForEditor()});await Play(true);}break;}
   case "newTheme":current=new ThemeDocument{Json=ThemeDocument.Blank("Untitled theme",settings.Width,settings.Height),Path="",Folder=AppPaths.Root,Background="",Video=false};Post(new{type="document",document=current.ForEditor()});break;
   case "selectDevice":SelectDevice((string)message["port"]);break;
   case "preview":await Play(false);break;case "play":await Play(true);break;case "stop":await Stop();break;
   case "saveTheme":await SaveEditor((JObject)message["document"]);break;
   case "saveAndPlay":await SaveEditor((JObject)message["document"]);await Play(true);break;
   case "import":await ImportThemes();break;case "export":await ExportTheme(message["document"] as JObject);break;
   case "remove":if(current!=null){await Stop();string removed=ThemeRepository.Remove(current.Path);status="Theme moved to Removed. Installed originals remain available.";current=null;await ReloadLibrary();}break;
   case "chooseBackground":await ChooseAsset(false);break;case "addImage":await ChooseAsset(true);break;
   case "settings":if(engine!=null)throw new InvalidOperationException("Stop this display before changing its output settings.");settings.Width=Math.Max(100,Math.Min(3840,(int?)message["width"]??settings.Width));settings.Height=Math.Max(100,Math.Min(2400,(int?)message["height"]??settings.Height));settings.Fps=(int?)message["fps"]==30?30:60;settings.Quality=Math.Max(30,Math.Min(95,(int?)message["quality"]??settings.Quality));settings.CacheMB=Math.Max(32,Math.Min(512,(int?)message["cacheMB"]??settings.CacheMB));settings.Rotation=(int?)message["rotation"]??-1;SaveSettings();break;
   case "resume":settings.Resume=(bool?)message["value"]??true;SaveSettings();break;
   case "startup":using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run",true)){if((bool?)message["value"]==true)key.SetValue("JonsboStudio","\""+Application.ExecutablePath+"\" --background");else key.DeleteValue("JonsboStudio",false);}break;
   case "scan":devices=await Task.Run(()=>JonsboTransport.Discover());LoadDeviceSettings();status=devices.Count+" supported display(s) found.";break;
   case "refreshLibrary":await ReloadLibrary();break;
   case "download":busy=true;status="Downloading native theme…";SendState();try{string path=await Task.Run(()=>OnlineCatalog.Download((string)message["id"],text=>{if(IsHandleCreated)BeginInvoke(new Action(()=>status=text));}));current=ThemeDocument.Load(path);settings.ThemePath=path;await ReloadLibrary();Post(new{type="document",document=current.ForEditor()});status="Theme imported. Apply it to the display when ready.";}finally{busy=false;}if((bool?)message["apply"]==true){Post(new{type="navigate",page="display"});await Play(true);}break;
   case "community":busy=true;status="Loading public community catalog…";try{var items=await Task.Run(()=>OnlineCatalog.Community(settings.Width+"×"+settings.Height));online=OnlineCatalog.BuiltIns();foreach(var item in items)online.Add(item);Post(new{type="online",items=online});status="Public catalog loaded. Store-account downloads open on the official page.";}finally{busy=false;}break;
   case "openStore":Process.Start("https://theme.screen-aio.com/theme/");break;
   case "openSource":{var item=online.OfType<JObject>().FirstOrDefault(x=>(string)x["id"]==(string)message["id"]);if(item!=null){var uri=new Uri((string)item["sourceUrl"]);if(uri.Scheme=="https"&&(uri.Host=="theme.screen-aio.com"||uri.Host=="res.hlinel.com"))Process.Start(uri.AbsoluteUri);}break;}
   case "clearCache":if(engines.Count>0)throw new InvalidOperationException("Stop both displays before clearing the prepared cache.");foreach(string file in Directory.GetFiles(AppPaths.Data("Cache")))if(file.EndsWith(".mjpg")||file.EndsWith(".mjpg.json"))File.Delete(file);status="Prepared cache cleared.";break;
   case "saveSettings":SaveSettings();status="Session saved on this PC.";break;
  }}catch(Exception ex){status=ex.Message;Post(new{type="error",message=ex.Message});}SendState();}
  async Task ReloadLibrary(){library=await Task.Run(()=>ThemeRepository.Scan());Post(new{type="library",items=library});}
  async Task SaveEditor(JObject document){if(document==null)return;busy=true;try{document["Type"]=0;string path=await Task.Run(()=>ThemeRepository.SaveEditor(document));current=ThemeDocument.Load(path);settings.ThemePath=path;SaveSettings();await ReloadLibrary();Post(new{type="document",document=current.ForEditor()});status="Theme saved to your local library.";}finally{busy=false;}}
  async Task ImportThemes(){using(var dialog=new OpenFileDialog{Filter="JONSBO themes|*.vmax;*.JONSBO;*.zip;*.json",Multiselect=true})if(dialog.ShowDialog(this)==DialogResult.OK){busy=true;try{string last="";foreach(string path in dialog.FileNames)last=await Task.Run(()=>ThemeRepository.Import(path));await ReloadLibrary();if(File.Exists(last)){current=ThemeDocument.Load(last);settings.ThemePath=last;Post(new{type="document",document=current.ForEditor()});SaveSettings();}status="Imported "+dialog.FileNames.Length+" theme(s).";}finally{busy=false;}}}
  async Task ExportTheme(JObject document){if(document!=null)await SaveEditor(document);if(current==null)return;using(var dialog=new SaveFileDialog{Filter="JONSBO native theme|*.vmax",FileName=current.Name+".vmax"})if(dialog.ShowDialog(this)==DialogResult.OK){busy=true;try{await Task.Run(()=>ThemeRepository.Export(current.Path,dialog.FileName));status="Native .vmax theme exported.";}finally{busy=false;}}}
  async Task ChooseAsset(bool image){using(var dialog=new OpenFileDialog{Filter=image?"Images|*.png;*.jpg;*.jpeg;*.bmp;*.gif":"Video or image|*.mp4;*.mkv;*.webm;*.mov;*.avi;*.png;*.jpg;*.jpeg;*.bmp;*.gif"})if(dialog.ShowDialog(this)==DialogResult.OK){string target=Path.Combine(AppPaths.Data("Media"),Guid.NewGuid().ToString("N")+Path.GetExtension(dialog.FileName));await Task.Run(()=>File.Copy(dialog.FileName,target));Post(new{type=image?"imageAsset":"backgroundAsset",path=target,url=AppPaths.AssetUrl(target),video=!(new[]{".png",".jpg",".jpeg",".bmp",".gif"}).Contains(Path.GetExtension(target).ToLowerInvariant())});}}
  public async Task Play(bool hardware){if(busy)return;if(current==null){status="Select a theme first.";return;}if(engine!=null)await Stop(false);busy=true;status=hardware?"Opening JONSBO display…":"Starting preview…";SendState();try{var next=new PlaybackEngine(current,settings,hardware);await Task.Run(()=>next.Start());engine=next;if(hardware){var selected=devices.FirstOrDefault(x=>x.port==settings.Port);if(selected!=null){selected.serial=next.Device;selected.width=next.NativeWidth;selected.height=next.NativeHeight;selected.name=next.NativeWidth==462&&next.NativeHeight==1920?"JONSBO DS916":next.NativeWidth==376&&next.NativeHeight==960?"JONSBO DS339":"JONSBO "+next.NativeWidth+" × "+next.NativeHeight;}}lastProduced=lastSent=lastBytes=0;lastTick=clock.Elapsed.TotalSeconds;status="Playing "+current.Name+". Frames prepare once and are reused.";SaveSettings();}catch(Exception ex){status=ex.Message;}finally{busy=false;SendState();}}
  public async Task Stop(bool remember=true){if(engine==null)return;var old=engine;engine=null;busy=true;try{await Task.Run(()=>old.Dispose());status="Playback stopped.";if(remember)SaveSettings();}catch(Exception ex){status="Stop: "+ex.Message;}finally{busy=false;previewFps=renderedFps=usbFps=0;SendState();}}
  void SaveSettings(){if(!persist)return;deviceSettings[settings.Port]=settings;foreach(var item in deviceSettings)item.Value.WasPlaying=engines.ContainsKey(item.Key);settings.Save();AppPaths.SaveJson(DeviceSettingsPath,JObject.FromObject(deviceSettings));}
  public void Restore(){ShowInTaskbar=true;Show();WindowState=FormWindowState.Normal;Activate();}
  public async Task Exit(){if(closing)return;if(busy){status="Finishing the current operation before exit…";var waiter=new System.Windows.Forms.Timer{Interval=100};waiter.Tick+=async(s,e)=>{if(busy)return;waiter.Stop();waiter.Dispose();await Exit();};waiter.Start();return;}SaveSettings();var running=engines.Values.ToArray();engines.Clear();await Task.Run(()=>{foreach(var item in running)item.Dispose();});closing=true;Close();}
  void SendState(){if(!ready)return;var active=engine;double now=clock.Elapsed.TotalSeconds,delta=now-lastTick;if(active!=null&&delta>=.4){renderedFps=(active.Produced-lastProduced)/delta;usbFps=(active.Sent-lastSent)/delta;mbps=(active.Bytes-lastBytes)/delta/1000000;lastProduced=active.Produced;lastSent=active.Sent;lastBytes=active.Bytes;lastTick=now;if(active.Error.Length>0)status=active.Error;}bool startup=false;try{using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run"))startup=key.GetValue("JonsboStudio")!=null;}catch{}Post(new{type="state",settings=settings,devices=devices,playingPorts=engines.Keys.ToArray(),busy=busy,playing=active!=null,hardware=active!=null&&active.Hardware,status=status,renderFps=renderedFps,usbFps=usbFps,previewFps=previewFps,encodeMs=active==null?0:active.EncodeMs,transferMs=active==null?0:active.TransferMs,prepared=active==null?0:active.Prepared,expected=active==null?0:active.ExpectedFrames,cacheComplete=active!=null&&active.PreparedComplete,cacheRam=active==null?0:active.RamMB,cacheDisk=active==null?0:active.DiskMB,sourceFps=active==null?0:active.SourceFps,dropped=active==null?0:active.Dropped,usbMBps=mbps,hostRam=Process.GetCurrentProcess().WorkingSet64/1048576.0,startup=startup,sensors=sensors.Latest.values,sensorVersion=sensors.Latest.version});}
  void PreviewTick(object ignored){if(previewStopped||!ready||!windowVisible||!previewPage)return;var active=engine;if(active==null)return;var frame=active.Latest;if(frame==null)return;long now=Stopwatch.GetTimestamp(),next=Interlocked.Read(ref previewDue);if(now<next)return;long interval=Stopwatch.Frequency/active.Fps,following=next==0?now+interval:next+interval;if(following<=now)following=now+interval;if(Interlocked.CompareExchange(ref previewDue,following,next)!=next)return;if(Interlocked.Increment(ref previewPending)>2){Interlocked.Decrement(ref previewPending);return;}
