    long sequence=Interlocked.Increment(ref previewSeq);BeginInvoke(new Action(()=>{try{if(previewStopped||!windowVisible||!ReferenceEquals(active,engine))return;Post(repeat?new{type="previewRepeat",data=(string)null,seq=sequence}:new{type="preview",data=data,seq=sequence});}finally{Interlocked.Decrement(ref previewPending);}}));
