  public async Task CaptureScreenshot(string path,string page){for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("Web interface did not initialize.");await web.CoreWebView2.ExecuteScriptAsync("navigate("+JsonConvert.SerializeObject(page)+")");await Task.Delay(700);using(var stream=File.Create(path))await web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}
  public async Task UiSmoke(){for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("UI did not initialize.");await web.CoreWebView2.ExecuteScriptAsync("send('newTheme');navigate('editor')");await Task.Delay(250);await web.CoreWebView2.ExecuteScriptAsync("app.doc.Name='UI smoke '+Date.now();document.getElementById('add-text').click();updateLayer('Text','Native roundtrip');updateLayer('Left',123);history(false);history(true);send('saveTheme',{document:app.doc});");for(int i=0;i<100&&(busy||current==null||string.IsNullOrEmpty(current.Path));i++)await Task.Delay(100);if(current==null||current.Texts.Count!=1||(string)current.Texts[0]["Text"]!="Native roundtrip"||(double)current.Texts[0]["Left"]!=123)throw new Exception("Editor save/undo/redo bridge failed.");string folder=Path.GetDirectoryName(current.Path);if(!folder.StartsWith(AppPaths.Data("Themes")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Editor did not save a private copy.");Directory.Delete(folder,true);Console.WriteLine("PASS: modern editor text, properties, undo, redo and native JSON save; installed files unchanged.");}
  public async Task<string> UiBenchmark(string path,string port){for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("UI did not initialize.");current=ThemeDocument.Load(path);settings.ThemePath=path;settings.Port=port;settings.Width=1920;settings.Height=462;settings.Quality=75;Post(new{type="document",document=current.ForEditor()});SendState();await web.CoreWebView2.ExecuteScriptAsync(string.IsNullOrEmpty(port)?"send('preview')":"send('play')");for(int i=0;i<200&&(engine==null||engine.Prepared<1);i++)await Task.Delay(100);if(engine==null)throw new Exception(status);for(int i=0;i<200&&!engine.PreparedComplete;i++)await Task.Delay(100);await Task.Delay(2000);long start=engine.Produced,startSent=engine.Sent;var process=Process.GetCurrentProcess();var before=process.TotalProcessorTime;var watch=Stopwatch.StartNew();await Task.Delay(5000);process.Refresh();string result=string.Format("UI render={0:F1} FPS; USB={1:F1} FPS; preview={2:F1} FPS; host CPU={3:F2}%; host RAM={4:F1}MB; error={5}",(engine.Produced-start)/watch.Elapsed.TotalSeconds,(engine.Sent-startSent)/watch.Elapsed.TotalSeconds,previewFps,100*(process.TotalProcessorTime-before).TotalSeconds/watch.Elapsed.TotalSeconds/Environment.ProcessorCount,process.WorkingSet64/1048576.0,engine.Error);await web.CoreWebView2.ExecuteScriptAsync("send('stop')");for(int i=0;i<100&&(engine!=null||busy);i++)await Task.Delay(100);return result;}
  public async Task<string> MultiDeviceBenchmark(string ds916,string ds339){for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("UI did not initialize.");SelectDevice("COM12");current=ThemeDocument.Load(ds916);settings.ThemePath=ds916;settings.Width=1920;settings.Height=462;await Play(true);if(engine==null)throw new Exception(status);SelectDevice(MsDisplayTransport.PortId);current=ThemeDocument.Load(ds339);settings.ThemePath=ds339;settings.Width=960;settings.Height=376;await Play(true);if(engine==null)throw new Exception(status);PlaybackEngine first=engines["COM12"],second=engines[MsDisplayTransport.PortId];for(int i=0;i<100&&(!first.PreparedComplete||!second.PreparedComplete);i++)await Task.Delay(100);long a=first.Sent,b=second.Sent;var watch=Stopwatch.StartNew();await Task.Delay(5000);if(first.Error.Length>0||second.Error.Length>0)throw new Exception(first.Error+" "+second.Error);return string.Format("DS916={0:F1} FPS; DS339={1:F1} FPS; both active={2}",(first.Sent-a)/watch.Elapsed.TotalSeconds,(second.Sent-b)/watch.Elapsed.TotalSeconds,engines.Count==2);}
